extends CharacterBody2D

@export var speed: float = 300.0
@export var jump_velocity: float = -450.0

func _physics_process(delta: float) -> void:
	if not is_on_floor():
		velocity += get_gravity() * delta
	if Input.is_action_just_pressed("jump") and is_on_floor():
		velocity.y = jump_velocity
	var dir := Input.get_axis("move_left", "move_right")
	velocity.x = dir * speed
	move_and_slide()

extends CharacterBody2D

@export var speed: float = 300.0

func _physics_process(_delta: float) -> void:
	var dir := Input.get_vector("move_left", "move_right", "move_up", "move_down")
	velocity = dir * speed
	move_and_slide()

extends Node

signal vida_mudou(atual: int, maximo: int)

var vida: int = 100

func levar_dano(qtd: int) -> void:
	vida = max(0, vida - qtd)
	vida_mudou.emit(vida, 100)

func _ready() -> void:
	vida_mudou.connect(_ao_mudar_vida)

func _ao_mudar_vida(atual: int, maximo: int) -> void:
	print("vida: %d/%d" % [atual, maximo])

extends Node
class_name Vida

signal vida_alterada(atual: int, maximo: int)
signal morreu

@export var vida_maxima: int = 100
var vida_atual: int

func _ready() -> void:
	vida_atual = vida_maxima

func receber_dano(qtd: int) -> void:
	if vida_atual <= 0:
		return
	vida_atual = clampi(vida_atual - qtd, 0, vida_maxima)
	vida_alterada.emit(vida_atual, vida_maxima)
	if vida_atual == 0:
		morreu.emit()

func curar(qtd: int) -> void:
	vida_atual = clampi(vida_atual + qtd, 0, vida_maxima)
	vida_alterada.emit(vida_atual, vida_maxima)

extends Area2D

@export var dano: int = 10

func _ready() -> void:
	body_entered.connect(_ao_entrar_corpo)
	area_entered.connect(_ao_entrar_area)

func _ao_entrar_corpo(corpo: Node2D) -> void:
	if corpo.has_method("receber_dano"):
		corpo.receber_dano(dano)

func _ao_entrar_area(area: Area2D) -> void:
	pass

extends Node

@export var cooldown: float = 0.5
var _tempo_restante: float = 0.0

func _process(delta: float) -> void:
	if _tempo_restante > 0.0:
		_tempo_restante -= delta

func pronto() -> bool:
	return _tempo_restante <= 0.0

func usar() -> bool:
	if not pronto():
		return false
	_tempo_restante = cooldown
	return true
